<?php
// This page shares the existing enquiry store and integration settings.
ini_set('display_errors', '0');
function bgb_reply($code, $body) {
    http_response_code($code);
    header('Content-Type: application/json; charset=utf-8');
    header('Cache-Control: no-store');
    echo json_encode($body, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}
function bgb_value($key, $limit = 180) {
    $value = $_POST[$key] ?? '';
    return is_string($value) ? trim(substr($value, 0, $limit)) : '';
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if ((int)($_SERVER['CONTENT_LENGTH'] ?? 0) > 16384) bgb_reply(413, ['ok'=>false,'error'=>'Please shorten your details and try again.']);
    if (bgb_value('website') !== '') bgb_reply(200, ['ok'=>true]);
    $origin = $_SERVER['HTTP_ORIGIN'] ?? '';
    if ($origin && !in_array(parse_url($origin, PHP_URL_HOST), ['bhavinjshah.com', 'www.bhavinjshah.com', 'localhost', '127.0.0.1'], true)) {
        bgb_reply(403, ['ok'=>false,'error'=>'Please submit this form from bhavinjshah.com.']);
    }
    $name = bgb_value('name', 100);
    $phone = preg_replace('/[\s()+-]/', '', bgb_value('phone', 30));
    if (strlen($phone) === 12 && substr($phone, 0, 2) === '91') $phone = substr($phone, 2);
    $city = bgb_value('city', 100);
    $email = bgb_value('email', 180);
    $options = [
        'decision'=>['Owner / Partner', 'Decision-maker'],
        'business_type'=>['Manufacturing', 'Trading / Wholesale', 'Retail', 'Service business', 'Agency / Professional firm', 'Other running business'],
        'years_in_business'=>['0-2 years', '3-7 years', '8-15 years', '15+ years'],
        'annual_turnover'=>['Under Rs 50 lakh', 'Rs 50 lakh - 2 crore', 'Rs 2 - 10 crore', 'Rs 10 crore+', 'Prefer to discuss'],
        'team_size'=>['Just me', '2-10', '11-50', '50+'],
        'main_challenge'=>['Sales are not growing', 'The team depends on me', 'Retaining good people', 'Work-life balance', 'Slow decision-making', 'Other business challenge']
    ];
    $errors = [];
    if (strlen($name) < 2) $errors['name'] = 'Enter your full name.';
    if (!preg_match('/^[6-9][0-9]{9}$/', $phone)) $errors['phone'] = 'Enter a valid 10-digit Indian mobile number.';
    if (strlen($city) < 2) $errors['city'] = 'Enter your city.';
    if ($email !== '' && !filter_var($email, FILTER_VALIDATE_EMAIL)) $errors['email'] = 'Enter a valid email address or leave this blank.';
    foreach ($options as $key=>$allowed) if (!in_array(bgb_value($key), $allowed, true)) $errors[$key] = 'Please select an option.';
    if (bgb_value('consent') !== 'yes') $errors['consent'] = 'Please allow the team to contact you about this session.';
    $requestId = bgb_value('request_id', 80);
    if (!preg_match('/^[a-zA-Z0-9-]{16,80}$/', $requestId)) $errors['form'] = 'Please refresh this page and try again.';
    if ($errors) bgb_reply(422, ['ok'=>false,'error'=>'Please check the highlighted details.','fields'=>$errors]);

    $fields = ['name'=>$name, 'phone'=>$phone, 'email'=>$email, 'city'=>$city, 'interest'=>'Business Growth Blueprint'];
    foreach ($options as $key=>$allowed) $fields[$key] = bgb_value($key);
    $fields['business_name'] = bgb_value('business_name');
    $fields['self_check'] = bgb_value('self_check', 2000);
    $fields['message'] = 'Business: '.$fields['business_name'].' | Type: '.$fields['business_type'].' | Years: '.$fields['years_in_business'].' | Turnover: '.$fields['annual_turnover'].' | Team: '.$fields['team_size'].' | Challenge: '.$fields['main_challenge'];
    $fields['session_date'] = '2026-11-20';
    $fields['session_time'] = '08:55-11:55 Asia/Kolkata';
    $fields['consent'] = 'Contact about this session by phone or WhatsApp';
    foreach (['utm_source','utm_medium','utm_campaign','utm_content','utm_term'] as $key) $fields[$key] = bgb_value($key);
    // Neutralize formula-like values before the configured spreadsheet receives them.
    foreach ($fields as $key=>$value) if (preg_match('/^[=+@\-\t\r]/', $value)) $fields[$key] = "'".$value;
    $root = dirname(__DIR__);
    $directory = $root.'/data';
    $store = $directory.'/enquiries.json';
    if (!is_dir($directory) && !@mkdir($directory, 0775, true)) bgb_reply(503, ['ok'=>false,'error'=>'We could not save your request. Please try again or call the team.']);
    $file = @fopen($store, 'c+');
    if (!$file || !flock($file, LOCK_EX)) bgb_reply(503, ['ok'=>false,'error'=>'We could not save your request. Please try again.']);
    $raw = stream_get_contents($file);
    $all = trim($raw) === '' ? [] : json_decode($raw, true);
    if (!is_array($all)) { flock($file, LOCK_UN); fclose($file); bgb_reply(503, ['ok'=>false,'error'=>'Registration is temporarily unavailable. Please contact the team.']); }
    $id = 'bgb_'.substr(hash('sha256', $requestId), 0, 20);
    $now = time(); $recent = 0;
    foreach ($all as $previous) {
        if (($previous['id'] ?? '') === $id) { flock($file, LOCK_UN); fclose($file); bgb_reply(200, ['ok'=>true,'reference'=>$id]); }
        if (($previous['form_type'] ?? '') === 'Business Growth Blueprint' && ($previous['ip'] ?? '') === ($_SERVER['REMOTE_ADDR'] ?? '') && ($previous['created_at'] ?? 0) > $now - 600) $recent++;
    }
    if ($recent >= 5) { flock($file, LOCK_UN); fclose($file); bgb_reply(429, ['ok'=>false,'error'=>'Too many requests. Please wait a few minutes or contact the team.']); }
    $record = ['id'=>$id,'date'=>(new DateTimeImmutable('now', new DateTimeZone('Asia/Kolkata')))->format('Y-m-d H:i:s'),'created_at'=>$now,'form_type'=>'Business Growth Blueprint','fields'=>$fields,'page_url'=>defined('BGB_PAGE_URL') ? BGB_PAGE_URL : 'https://www.bhavinjshah.com/business-growth-blueprint/','ip'=>$_SERVER['REMOTE_ADDR'] ?? ''];
    $all[] = $record;
    $json = json_encode($all, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
    rewind($file);
    $written = $json !== false ? fwrite($file, $json) : false;
    $saved = $written !== false && $written === strlen($json) && ftruncate($file, strlen($json)) && fflush($file);
    flock($file, LOCK_UN); fclose($file);
    if (!$saved) bgb_reply(503, ['ok'=>false,'error'=>'We could not save your request. Please try again or call the team.']);

    $settingsPath = $directory.'/settings.json';
    $settings = is_file($settingsPath) ? json_decode(file_get_contents($settingsPath), true) : [];
    if (!is_array($settings)) $settings = [];
    $payload = array_merge(['form_type'=>$record['form_type'],'date'=>$record['date']], $fields, ['page_url'=>$record['page_url']]);
    foreach (['webhook_url', 'webhook_url2'] as $key) {
        $hook = trim($settings[$key] ?? '');
        if (!$hook || !filter_var($hook, FILTER_VALIDATE_URL) || !in_array(parse_url($hook, PHP_URL_SCHEME), ['http','https'], true)) continue;
        $body = json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
        if (function_exists('curl_init')) {
            $ch = curl_init($hook);
            curl_setopt_array($ch, [CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$body,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_RETURNTRANSFER=>true,CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>8,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_SSL_VERIFYPEER=>true]);
            $result = curl_exec($ch); $status = curl_getinfo($ch, CURLINFO_HTTP_CODE); unset($ch);
            if ($result === false || $status >= 400) error_log('BGB integration delivery failed for '.$id.' ('.$key.'). Enquiry remains saved in admin.');
        } else {
            $context = stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\n",'content'=>$body,'timeout'=>8]]);
            if (@file_get_contents($hook, false, $context) === false) error_log('BGB integration delivery failed for '.$id.'. Enquiry remains saved in admin.');
        }
    }
    if (!empty($settings['notify_email']) && filter_var($settings['notify_email'], FILTER_VALIDATE_EMAIL)) {
        $body = 'New Business Growth Blueprint registration'."\n".'Reference: '.$id."\n";
        foreach ($fields as $key=>$value) $body .= $key.': '.$value."\n";
        @mail($settings['notify_email'], 'Business Growth Blueprint registration', $body, 'From: no-reply@bhavinjshah.com');
    }
    bgb_reply(200, ['ok'=>true,'reference'=>$id]);
}
if (!in_array($_SERVER['REQUEST_METHOD'], ['GET','HEAD'], true)) bgb_reply(405, ['ok'=>false,'error'=>'Method not allowed.']);
header('Content-Type: text/html; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');
?>
